'use strict';

window.CabinetAudio = (function () {
    const clips = new Map();
    const queues = {
        high: [],
        normal: [],
        low: []
    };

    let playing = false;

    /** Audio event map — 16 distinct WAV files replacing single press.mp3.
     *  All files in /assets/audio/*.wav, generated by scripts/gen_audio.py */
    const DEFAULT_EVENTS = Object.freeze({
        // Button press (generic, legacy compat)
        press:          { src: '/assets/audio/press.wav',          volume: 0.3,  priority: 'normal' },
        invalid:        { src: '/assets/audio/press.wav',          volume: 0.18, priority: 'high'   },

        // Deal phase — mechanical card thud per card (~50ms)
        deal:           { src: '/assets/audio/deal.wav',           volume: 0.25, priority: 'normal' },

        // Hold toggle — click
        hold:           { src: '/assets/audio/hold.wav',           volume: 0.15, priority: 'low'    },

        // Draw phase — card flip/replacement
        draw:           { src: '/assets/audio/draw.wav',           volume: 0.25, priority: 'normal' },

        // Win tiers — distinct for each hand strength
        'win-small':    { src: '/assets/audio/win-small.wav',      volume: 0.30, priority: 'high'   },  // 2P, 3K
        'win-medium':   { src: '/assets/audio/win-medium.wav',     volume: 0.35, priority: 'high'   },  // Straight, Flush, FH
        'win-big':      { src: '/assets/audio/win-big.wav',        volume: 0.40, priority: 'high'   },  // 4K, SF
        'win-jackpot':  { src: '/assets/audio/win-jackpot.wav',    volume: 0.50, priority: 'high'   },  // Jackpot hit

        // Legacy win/compat aliases
        win:            { src: '/assets/audio/win-medium.wav',     volume: 0.35, priority: 'high'   },
        collect:        { src: '/assets/audio/win-small.wav',      volume: 0.22, priority: 'low'    },
        jackpot:        { src: '/assets/audio/win-jackpot.wav',    volume: 0.50, priority: 'high'   },

        // Double-up phase
        'du-shuffle':   { src: '/assets/audio/du-shuffle.wav',     volume: 0.25, priority: 'normal' },  // Rapid card cycling
        'du-reveal':    { src: '/assets/audio/du-reveal.wav',      volume: 0.30, priority: 'high'   },  // Card snap reveal
        'du-win':       { src: '/assets/audio/du-win.wav',         volume: 0.35, priority: 'high'   },  // Correct guess
        'du-lose':      { src: '/assets/audio/du-lose.wav',        volume: 0.28, priority: 'high'   },  // Wrong guess

        // Legacy DU aliases
        doubleUpWin:    { src: '/assets/audio/du-win.wav',         volume: 0.35, priority: 'high'   },
        doubleUpLose:   { src: '/assets/audio/du-lose.wav',        volume: 0.25, priority: 'normal' },
        doubleup:       { src: '/assets/audio/du-win.wav',         volume: 0.30, priority: 'normal' },
        doubleUp:       { src: '/assets/audio/du-win.wav',         volume: 0.30, priority: 'normal' },

        // 5♠ Lucky5 SafeFail — ethereal chime
        lucky5:         { src: '/assets/audio/lucky5.wav',         volume: 0.40, priority: 'high'   },

        // Machine close — alarm bell + counter tick
        machineClose:   { src: '/assets/audio/machine-close.wav',  volume: 0.40, priority: 'high'   },

        // Bet ramp — rapid credit drain ticking
        'bet-ramp':     { src: '/assets/audio/bet-ramp.wav',       volume: 0.20, priority: 'normal' },

        // Single credit tick
        'credit-tick':  { src: '/assets/audio/credit-tick.wav',    volume: 0.12, priority: 'low'    },

        // Cash in/out
        cashIn:         { src: '/assets/audio/win-small.wav',      volume: 0.20, priority: 'low'    },
        cashOut:        { src: '/assets/audio/win-medium.wav',     volume: 0.30, priority: 'normal' },

        // Bonus claim
        bonusClaim:     { src: '/assets/audio/win-big.wav',        volume: 0.40, priority: 'high'   }
    });

    function _getEventMap() {
        const cfg = (typeof GAME_CONFIG !== 'undefined' && GAME_CONFIG.audio) ? GAME_CONFIG.audio : null;
        return cfg && cfg.events ? { ...DEFAULT_EVENTS, ...cfg.events } : DEFAULT_EVENTS;
    }

    function _ensureClip(name) {
        if (clips.has(name)) return clips.get(name);
        const eventDef = _getEventMap()[name];
        if (!eventDef || !eventDef.src) return null;
        const audio = new Audio(eventDef.src);
        audio.preload = 'auto';
        audio.volume = typeof eventDef.volume === 'number' ? eventDef.volume : 0.3;
        clips.set(name, audio);
        return audio;
    }

    function preload() {
        Object.keys(_getEventMap()).forEach(_ensureClip);
    }

    function _nextQueueItem() {
        return queues.high.shift() || queues.normal.shift() || queues.low.shift() || null;
    }

    function _pump() {
        if (playing) return;
        const item = _nextQueueItem();
        if (!item) return;

        const clip = _ensureClip(item.name);
        if (!clip) return;

        playing = true;
        clip.pause();
        clip.currentTime = 0;
        clip.volume = typeof item.volume === 'number' ? item.volume : clip.volume;

        const finish = () => {
            clip.removeEventListener('ended', finish);
            clip.removeEventListener('error', finish);
            playing = false;
            _pump();
        };

        clip.addEventListener('ended', finish, { once: true });
        clip.addEventListener('error', finish, { once: true });
        const maybePromise = clip.play();
        if (maybePromise && typeof maybePromise.catch === 'function') {
            maybePromise.catch(() => {
                playing = false;
                _pump();
            });
        }
    }

    function queue(eventName, options) {
        const eventDef = _getEventMap()[eventName];
        if (!eventDef) return;
        const priority = (options && options.priority) || eventDef.priority || 'normal';
        queues[priority] = queues[priority] || queues.normal;
        queues[priority].push({
            name: eventName,
            volume: options && typeof options.volume === 'number' ? options.volume : eventDef.volume
        });
        _pump();
    }

    function playNow(eventName, options) {
        const clip = _ensureClip(eventName);
        if (!clip) return;
        clip.pause();
        clip.currentTime = 0;
        clip.volume = typeof options?.volume === 'number' ? options.volume : clip.volume;
        clip.play().catch(() => {});
    }

    return {
        preload,
        queue,
        playNow
    };
})();